from typing import List

class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        OFF = 1800
        if abs(k) > OFF:
            return -1
        target = k + OFF
        best = -1

        # Case B: subsequence containing at least one zero -> product 0
        if 0 in nums:
            M = [[0, 0], [0, 0]]
            M[0][0] = 1 << OFF   # empty subsequence, sum 0, parity 0, no zero used
            for x in nums:
                N = [[M[0][0], M[0][1]], [M[1][0], M[1][1]]]
                for p in (0, 1):
                    for z in (0, 1):
                        m = M[p][z]
                        if not m:
                            continue
                        nz = z | (1 if x == 0 else 0)
                        if p == 0:
                            N[1][nz] |= m << x
                        else:
                            N[0][nz] |= m >> x
                M = N
            if ((M[0][1] | M[1][1]) >> target) & 1:
                best = 0

        # Case A: subsequence without zeros, product in [1, limit]
        dp = {}  # product -> [mask parity0, mask parity1]  (non-empty subsequences only)
        for x in nums:
            if x == 0:
                continue
            add = {}
            if x <= limit:
                e = add.get(x)
                if e is None:
                    e = [0, 0]
                    add[x] = e
                e[1] |= 1 << (OFF + x)
            for q, ms in dp.items():
                nq = q * x
                if nq > limit:
                    continue
                m0 = ms[0]
                m1 = ms[1]
                e = add.get(nq)
                if e is None:
                    e = [0, 0]
                    add[nq] = e
                if m0:
                    e[1] |= m0 << x
                if m1:
                    e[0] |= m1 >> x
            for q, e in add.items():
                d = dp.get(q)
                if d is None:
                    dp[q] = e
                else:
                    d[0] |= e[0]
                    d[1] |= e[1]

        for q, ms in dp.items():
            if q > best and (((ms[0] | ms[1]) >> target) & 1):
                best = q

        return best

