class Solution:
    def minimumCost(self, nums: List[int], cost: List[int], k: int) -> int:
        n = len(nums)
        N = [0]*(n+1)
        C = [0]*(n+1)
        for i in range(n):
            N[i+1] = N[i] + nums[i]
            C[i+1] = C[i] + cost[i]
        Cn = C[n]
        dp = [0]*(n+1)
        for r in range(1, n+1):
            x = N[r] + k
            best = None
            for l in range(r):
                v = dp[l] - x*C[l]
                if best is None or v < best:
                    best = v
            dp[r] = best + N[r]*C[r] + k*Cn
        return dp[n]

