class Solution:
    def minOperations(self, queries: List[List[int]]) -> int:
        def f(n):
            if n <= 0:
                return 0
            total = 0
            k = 1
            lo = 1
            while lo <= n:
                hi = min(n, lo * 4 - 1)
                total += k * (hi - lo + 1)
                lo *= 4
                k += 1
            return total

        res = 0
        for l, r in queries:
            s = f(r) - f(l - 1)
            res += (s + 1) // 2
        return res

class Solution:
    def beautifulNumbers(self, l: int, r: int) -> int:
        maxlen = len(str(r))
        # dp[k]: dict (sum, prod) -> count  over k-digit sequences of digits 1..9
        dp = [None] * (maxlen + 1)
        dp[0] = {(0, 1): 1}
        for k in range(1, maxlen + 1):
            cur = {}
            for (s0, p0), c in dp[k - 1].items():
                for d in range(1, 10):
                    key = (s0 + d, p0 * d)
                    cur[key] = cur.get(key, 0) + c
            dp[k] = cur

        # good[k]: how many k-digit (digits 1..9) numbers are beautiful
        good = [0] * (maxlen + 1)
        for k in range(1, maxlen + 1):
            tot = 0
            for (s0, p0), c in dp[k].items():
                if p0 % s0 == 0:
                    tot += c
            good[k] = tot

        # precompute item lists for speed
        items = [list(dp[k].items()) for k in range(maxlen + 1)]

        def count_no_zero(N, s, n):
            # count of x in [1,N] with no zero digit
            total = 0
            for L in range(1, n):
                total += 9 ** L
            for i in range(n):
                di = int(s[i])
                hi = di - 1
                if hi >= 1:
                    total += min(hi, 9) * (9 ** (n - 1 - i))
                if di == 0:
                    return total
            return total + 1

        def combine(ns, np_, k):
            if k == 0:
                return 1 if np_ % ns == 0 else 0
            tot = 0
            for (s1, p1), c in items[k]:
                if (np_ * p1) % (ns + s1) == 0:
                    tot += c
            return tot

        def count(N):
            if N <= 0:
                return 0
            s = str(N)
            n = len(s)
            nz = count_no_zero(N, s, n)
            res = N - nz  # all numbers containing a zero digit are beautiful
            for L in range(1, n):
                res += good[L]
            sum0 = 0
            prod0 = 1
            broke = False
            for i in range(n):
                di = int(s[i])
                k = n - 1 - i
                hi = min(di - 1, 9)
                if hi >= 1:
                    for d in range(1, hi + 1):
                        res += combine(sum0 + d, prod0 * d, k)
                if di == 0:
                    broke = True
                    break
                sum0 += di
                prod0 *= di
            if not broke:
                if prod0 % sum0 == 0:
                    res += 1
            return res

        return count(r) - count(l - 1)

