class Solution:
    def longestCommonPrefix(self, words: List[str], k: int) -> List[int]:
        n = len(words)
        if n - 1 < k:
            return [0] * n

        children = [{}]
        cnt = [0]
        dep = [0]

        for w in words:
            node = 0
            for ch in w:
                ch_map = children[node]
                nxt = ch_map.get(ch, -1)
                if nxt < 0:
                    nxt = len(cnt)
                    children.append({})
                    cnt.append(0)
                    dep.append(dep[node] + 1)
                    ch_map[ch] = nxt
                node = nxt
                cnt[node] += 1

        maxdep = 0
        for d in dep:
            if d > maxdep:
                maxdep = d

        cntAtDepth = [0] * (maxdep + 2)
        for v in range(1, len(cnt)):
            if cnt[v] >= k:
                cntAtDepth[dep[v]] += 1

        M = 0
        for d in range(maxdep, 0, -1):
            if cntAtDepth[d] > 0:
                M = d
                break

        ans = [0] * n
        if M == 0:
            return ans

        kp1 = k + 1
        for i in range(n):
            w = words[i]
            L = len(w)
            node = 0
            A = 0
            m = 0
            d = 0
            for ch in w:
                node = children[node][ch]
                c = cnt[node]
                d += 1
                if c >= k:
                    m = d
                    if c >= kp1:
                        A = d
                else:
                    break

            B = 0
            if M > L:
                B = M
            else:
                for dd in range(M, 0, -1):
                    avail = cntAtDepth[dd] - (1 if dd <= m else 0)
                    if avail > 0:
                        B = dd
                        break

            ans[i] = A if A > B else B

        return ans

