def main():
    data = sys.stdin.read().split()
    idx = 0
    N = int(data[idx]); idx+=1
    M = int(data[idx]); idx+=1
    K = int(data[idx]); idx+=1
    edges_in = []
    for _ in range(M):
        u = int(data[idx]); idx+=1
        v = int(data[idx]); idx+=1
        edges_in.append((u,v))

    INF = 1 << 40

    def mincut(d, limit):
        # nodes: (v,i) -> (v-1)*d + (i-1), v in 1..N, i in 1..d
        n = N*d + 2
        S = N*d
        T = N*d + 1
        graph = [[] for _ in range(n)]
        def add(a, b, c):
            graph[a].append([b, c, len(graph[b])])
            graph[b].append([a, 0, len(graph[a])-1])
        def nid(v, i):
            return (v-1)*d + (i-1)
        # monotonicity chains
        for v in range(1, N+1):
            for i in range(1, d):
                add(nid(v,i+1), nid(v,i), INF)
        # p(1)=0
        for i in range(1, d+1):
            add(nid(1,i), T, INF)
        # p(N)=d
        for i in range(1, d+1):
            add(S, nid(N,i), INF)
        # pairwise
        for (u,v) in edges_in:
            for i in range(1, d+1):
                add(nid(v,i), nid(u,i), 1)
            for i in range(2, d+1):
                add(nid(v,i), nid(u,i-1), INF)

        flow = 0
        level = [0]*n
        it = [0]*n
        while True:
            # bfs
            for i in range(n):
                level[i] = -1
            level[S] = 0
            q = deque([S])
            while q:
                x = q.popleft()
                for e in graph[x]:
                    if e[1] > 0 and level[e[0]] < 0:
                        level[e[0]] = level[x] + 1
                        q.append(e[0])
            if level[T] < 0:
                break
            for i in range(n):
                it[i] = 0
            # dfs (iterative)
            while True:
                # find augmenting path
                stack = [S]
                path = []
                found = False
                while stack:
                    x = stack[-1]
                    if x == T:
                        found = True
                        break
                    advanced = False
                    while it[x] < len(graph[x]):
                        e = graph[x][it[x]]
                        if e[1] > 0 and level[e[0]] == level[x] + 1:
                            stack.append(e[0])
                            path.append((x, it[x]))
                            advanced = True
                            break
                        it[x] += 1
                    if not advanced:
                        level[x] = -1
                        stack.pop()
                        if path:
                            px, pi = path.pop()
                            it[px] += 1
                if not found:
                    break
                # bottleneck
                f = INF
                for (x, ei) in path:
                    e = graph[x][ei]
                    if e[1] < f:
                        f = e[1]
                for (x, ei) in path:
                    e = graph[x][ei]
                    e[1] -= f
                    graph[e[0]][e[2]][1] += f
                flow += f
                if flow > limit:
                    return flow
            if flow > limit:
                return flow
        return flow

    best = 0
    for d in range(1, N):
        c = mincut(d, K)
        if c <= K:
            best = d
    print(best)

