from collections import deque

def normal_form(s, X, Y):
    blocks = [[0, 0, deque()]]   # [site zero-run len, landed ones, rest runs]
    for m in re.finditer('0+|1+', s):
        seg = m.group()
        L = len(seg)
        blk = blocks[-1]
        if seg[0] == '0':
            rest = blk[2]
            if rest:
                last = rest[-1]
                if last[0] == 0:
                    nl = last[1] + L
                    if nl % X:
                        rest.pop()
                        blocks.append([nl, 0, deque()])
                    else:
                        last[1] = nl
                else:
                    if L % X:
                        blocks.append([L, 0, deque()])
                    else:
                        rest.append([0, L])
            elif blk[1] > 0:
                if L % X:
                    blocks.append([L, 0, deque()])
                else:
                    rest.append([0, L])
            elif blk[0] > 0:
                nz = blk[0] + L
                if nz % X == 0:
                    blocks.pop()
                    blocks[-1][2].append([0, nz])
                else:
                    blk[0] = nz
            else:
                if L % X:
                    blocks.append([L, 0, deque()])
                else:
                    rest.append([0, L])
        else:
            p, rem = divmod(L, Y)
            if p:
                z = blk[0]
                if z >= X:
                    r = z % X
                    blk[2].appendleft([0, z - r])
                    blk[0] = r
                blk[1] += p * Y
            if rem:
                rest = blk[2]
                if rest:
                    last = rest[-1]
                    if last[0] == 1:
                        last[1] += rem
                    else:
                        rest.append([1, rem])
                elif blk[1] > 0:
                    blk[1] += rem
                else:
                    rest.append([1, rem])
    parts = []
    for z, ones, rest in blocks:
        if z:
            parts.append('0' * z)
        if ones:
            parts.append('1' * ones)
        for ch, l in rest:
            parts.append(('0' if ch == 0 else '1') * l)
    return ''.join(parts)

