class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        byB = [[] for _ in range(n + 1)]
        for a, b in conflictingPairs:
            if a > b:
                a, b = b, a
            byB[b].append(a)
        gain = [0] * (n + 2)
        best1 = 0
        best2 = 0
        base = 0
        for r in range(1, n + 1):
            for a in byB[r]:
                if a > best1:
                    best2 = best1
                    best1 = a
                elif a > best2:
                    best2 = a
            base += r - best1
            if best1 > 0:
                gain[best1] += best1 - best2
        return base + max(gain)

