class Solution:
    def generateString(self, str1: str, str2: str) -> str:
        n = len(str1)
        m = len(str2)
        L = n + m - 1
        s2 = str2.encode()

        # Z-function of str2
        z = [0] * m
        if m > 0:
            z[0] = m
            l, r = 0, 0
            for i in range(1, m):
                if i < r:
                    z[i] = min(r - i, z[i - l])
                while i + z[i] < m and s2[z[i]] == s2[i + z[i]]:
                    z[i] += 1
                if i + z[i] > r:
                    l, r = i, i + z[i]

        tpos = [i for i in range(n) if str1[i] == 'T']

        # check consistency of overlapping T placements (adjacent pairs suffice)
        for k in range(1, len(tpos)):
            d = tpos[k] - tpos[k - 1]
            if d < m:
                if z[d] != m - d:
                    return ""

        word = bytearray(b'a' * L)
        fixed = bytearray(L)
        ONES = b'\x01' * m
        for i in tpos:
            word[i:i + m] = s2
            fixed[i:i + m] = ONES

        freelist = [i for i in range(L) if not fixed[i]]

        bchar = ord('b')
        for i in range(n):
            if str1[i] == 'F':
                if word[i:i + m] == s2:
                    idx = bisect_right(freelist, i + m - 1) - 1
                    if idx < 0 or freelist[idx] < i:
                        return ""
                    j = freelist.pop(idx)
                    word[j] = bchar

        return word.decode()

