class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        fact = [1] * (n + 2)
        for i in range(1, n + 2):
            fact[i] = fact[i - 1] * i

        used = [False] * (n + 1)
        o = (n + 1) // 2  # odds available
        e = n // 2        # evens available
        res = []
        prev_par = None

        for pos in range(n):
            chosen = False
            for v in range(1, n + 1):
                if used[v]:
                    continue
                par = v % 2
                if prev_par is not None and par == prev_par:
                    continue
                no = o - (1 if par == 1 else 0)
                ne = e - (1 if par == 0 else 0)
                m = n - pos - 1
                startpar = 1 - par
                s = (m + 1) // 2
                t = m // 2
                if startpar == 1:
                    need_odd, need_even = s, t
                else:
                    need_even, need_odd = s, t
                if need_odd != no or need_even != ne:
                    c = 0
                else:
                    c = fact[no] * fact[ne]
                if k > c:
                    k -= c
                else:
                    used[v] = True
                    res.append(v)
                    o, e = no, ne
                    prev_par = par
                    chosen = True
                    break
            if not chosen:
                return []
        return res

