    _HAVE_NP = True
except Exception:
    _HAVE_NP = False


class Solution:
    def maxDistance(self, side: int, points: List[List[int]], k: int) -> int:
        s = side
        pos = []
        for x, y in points:
            if y == 0:
                t = x
            elif x == s:
                t = s + y
            elif y == s:
                t = 3 * s - x
            else:
                t = 4 * s - y
            pos.append(t)
        pos.sort()
        n = len(pos)
        total = 4 * s
        P = pos + [t + total for t in pos]
        INF = 2 * n

        if _HAVE_NP:
            Parr = _np.array(P, dtype=_np.int64)
            Phead = Parr[:n]

            def check(d):
                nxt = _np.empty(2 * n + 1, dtype=_np.int64)
                v = _np.searchsorted(Parr, Phead + d, side='left')
                nxt[:n] = v
                nxt[n:2 * n] = _np.where(v < n, v + n, INF)
                nxt[2 * n] = INF
                e = k - 1
                res = None
                base = nxt
                while e:
                    if e & 1:
                        res = base.copy() if res is None else base[res]
                    e >>= 1
                    if e:
                        base = base[base]
                j = res[:n]
                mask = j < INF
                if not mask.any():
                    return False
                jj = _np.where(mask, j, 0)
                return bool(((Parr[jj] - Phead <= total - d) & mask).any())
        else:
            def check(d):
                nxt = [INF] * (2 * n + 1)
                j = 0
                m2 = 2 * n
                for i in range(n):
                    target = P[i] + d
                    if j <= i:
                        j = i + 1
                    while j < m2 and P[j] < target:
                        j += 1
                    nxt[i] = j
                for i in range(n, m2):
                    v = nxt[i - n]
                    nxt[i] = v + n if v < n else INF
                nxt[m2] = INF
                e = k - 1
                res = None
                base = nxt
                while e:
                    if e & 1:
                        res = list(base) if res is None else [base[x] for x in res]
                    e >>= 1
                    if e:
                        base = [base[x] for x in base]
                lim = total - d
                for i in range(n):
                    jj = res[i]
                    if jj < INF and P[jj] - P[i] <= lim:
                        return True
                return False

        lo, hi = 1, total // k
        ans = 0
        while lo <= hi:
            mid = (lo + hi) // 2
            if check(mid):
                ans = mid
                lo = mid + 1
            else:
                hi = mid - 1
        return ans

