class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        n = len(s)
        i1 = p.index('*')
        i2 = p.index('*', i1 + 1)
        a = p[:i1]
        b = p[i1+1:i2]
        c = p[i2+1:]

        def find_all(text, pat):
            m = len(pat)
            if m == 0:
                return list(range(len(text) + 1))
            if m > len(text):
                return []
            # KMP
            fail = [0] * m
            k = 0
            for i in range(1, m):
                ch = pat[i]
                while k > 0 and pat[k] != ch:
                    k = fail[k-1]
                if pat[k] == ch:
                    k += 1
                fail[i] = k
            res = []
            k = 0
            for i, ch in enumerate(text):
                while k > 0 and pat[k] != ch:
                    k = fail[k-1]
                if pat[k] == ch:
                    k += 1
                if k == m:
                    res.append(i - m + 1)
                    k = fail[k-1]
            return res

        A = find_all(s, a)
        B = find_all(s, b)
        C = find_all(s, c)

        if not A or not B or not C:
            return -1

        la, lb, lc = len(a), len(b), len(c)
        best = -1

        for j in B:
            # largest i in A with i <= j - la
            lim = j - la
            if lim < 0:
                continue
            idx = bisect_right(A, lim) - 1
            if idx < 0:
                continue
            i = A[idx]
            # smallest k in C with k >= j + lb
            need = j + lb
            idx2 = bisect_left(C, need)
            if idx2 >= len(C):
                break
            k = C[idx2]
            length = k + lc - i
            if best == -1 or length < best:
                best = length

        return best

