    def countSubstrings(self, s: str) -> int:
        n = len(s)
        ans = 0
        # prefix sums mod 3 and mod 9
        cnt3 = [0]*3
        cnt9 = [0]*9
        cnt3[0] = 1
        cnt9[0] = 1
        sum3 = 0
        sum9 = 0
        # residues mod 7 for all suffixes ending at current position
        cnt7 = [0]*7

        digits = [ord(c)-48 for c in s]

        for j in range(n):
            d = digits[j]
            # update mod7 residue counts
            new7 = [0]*7
            for r in range(7):
                c = cnt7[r]
                if c:
                    new7[(10*r + d) % 7] += c
            new7[d % 7] += 1
            cnt7 = new7

            # update prefix sums
            sum3 = (sum3 + d) % 3
            sum9 = (sum9 + d) % 9

            if d == 0:
                pass
            elif d == 1 or d == 2 or d == 5:
                ans += j + 1
            elif d == 3:
                ans += cnt3[sum3]
            elif d == 6:
                ans += cnt3[sum3]
            elif d == 9:
                ans += cnt9[sum9]
            elif d == 4:
                ans += 1
                if j >= 1 and digits[j-1] % 2 == 0:
                    ans += j
            elif d == 8:
                ans += 1
                if j >= 1:
                    a = digits[j-1]
                    if (2*a) % 8 == 0:
                        ans += 1
                if j >= 2:
                    a = digits[j-1]
                    b = digits[j-2]
                    if (4*b + 2*a) % 8 == 0:
                        ans += j - 1
            elif d == 7:
                ans += cnt7[0]

            cnt3[sum3] += 1
            cnt9[sum9] += 1

        return ans

