class Solution:
    def maxScore(self, points: List[int], m: int) -> int:
        n = len(points)

        def feasible(t):
            if t == 0:
                return True
            moves = 0
            carry = 0
            for p in points:
                moves += 1
                if moves > m:
                    return False
                v = carry + 1
                # k = ceil(t/p)
                k = -(-t // p)
                if v < k:
                    extra = k - v
                    moves += 2 * extra
                    if moves > m:
                        return False
                    carry = extra
                else:
                    carry = 0
            return moves <= m

        lo, hi = 0, m * min(points)
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if feasible(mid):
                lo = mid
            else:
                hi = mid - 1
        return lo

