class Solution:
    def minimumIncrements(self, nums: List[int], target: List[int]) -> int:
        k = len(target)
        n = len(nums)
        INF = float('inf')

        # lcm for every non-empty subset
        lcms = [1] * (1 << k)
        for s in range(1, 1 << k):
            L = 1
            for i in range(k):
                if (s >> i) & 1:
                    t = target[i]
                    L = L // gcd(L, t) * t
            lcms[s] = L

        # top-4 cheapest candidates per subset
        cands = [None] * (1 << k)
        for s in range(1, 1 << k):
            L = lcms[s]
            lst = []
            thr = INF
            for i, x in enumerate(nums):
                c = (-x) % L
                if c < thr:
                    lst.append((c, i))
                    if len(lst) > 8:
                        lst.sort()
                        lst = lst[:4]
                        thr = lst[-1][0]
                        if thr == 0:
                            break
            lst.sort()
            cands[s] = lst[:4]

        # enumerate set partitions of {0..k-1} as lists of masks
        partitions = []

        def gen(i, groups):
            if i == k:
                partitions.append(list(groups))
                return
            bit = 1 << i
            for j in range(len(groups)):
                groups[j] |= bit
                gen(i + 1, groups)
                groups[j] ^= bit
            groups.append(bit)
            gen(i + 1, groups)
            groups.pop()

        gen(0, [])

        best_global = INF

        for part in partitions:
            # order groups by their cheapest candidate descending? simple DFS with pruning
            m = len(part)
            best = INF

            def rec(j, used, cur):
                nonlocal best
                if cur >= best:
                    return
                if j == m:
                    best = cur
                    return
                for c, idx in cands[part[j]]:
                    if idx in used:
                        continue
                    if cur + c >= best:
                        break
                    used.add(idx)
                    rec(j + 1, used, cur + c)
                    used.discard(idx)

            rec(0, set(), 0)
            if best < best_global:
                best_global = best

        return int(best_global)

