    MOD = 998244353
    size = 1 << N
    chars = sorted(set(S))
    weights = [1]*len(chars)
    other = 26 - len(chars)
    charlist = list(chars)
    if other > 0:
        charlist.append(None)  # represents any char not in S
        weights.append(other)

    # precompute transitions
    trans = [[0]*len(charlist) for _ in range(size)]
    for mask in range(size):
        # decode dp
        dp = [0]*(N+1)
        for j in range(1, N+1):
            dp[j] = dp[j-1] + ((mask >> (j-1)) & 1)
        for ci, c in enumerate(charlist):
            nd = [0]*(N+1)
            for j in range(1, N+1):
                v = nd[j-1]
                if dp[j] > v:
                    v = dp[j]
                if c is not None and S[j-1] == c:
                    if dp[j-1] + 1 > v:
                        v = dp[j-1] + 1
                nd[j] = v
            nm = 0
            for j in range(1, N+1):
                if nd[j] - nd[j-1] == 1:
                    nm |= (1 << (j-1))
            trans[mask][ci] = nm

    cur = [0]*size
    cur[0] = 1
    nchars = len(charlist)
    for _ in range(M):
        nxt = [0]*size
        for mask in range(size):
            v = cur[mask]
            if v == 0:
                continue
            tr = trans[mask]
            for ci in range(nchars):
                nxt[tr[ci]] = (nxt[tr[ci]] + v * weights[ci]) % MOD
        cur = nxt

    ans = [0]*(N+1)
    for mask in range(size):
        if cur[mask]:
            k = bin(mask).count('1')
            ans[k] = (ans[k] + cur[mask]) % MOD
