class Solution:
    def minMaxSubarraySum(self, nums: List[int], k: int) -> int:
        n = len(nums)
        K = k + 1

        def cnt(a, b):
            t = K - b
            if t < 0:
                t = 0
            if t > a:
                t = a
            total = t * b
            u = a if a < K - 1 else K - 1
            if u > t:
                total += ((K - t - 1) + (K - u)) * (u - t) // 2
            return total

        def maxsum(arr):
            # previous strictly greater
            L = [-1] * n
            stack = []
            for i in range(n):
                ai = arr[i]
                while stack and arr[stack[-1]] <= ai:
                    stack.pop()
                L[i] = stack[-1] if stack else -1
                stack.append(i)
            # next greater or equal
            R = [n] * n
            stack = []
            for i in range(n - 1, -1, -1):
                ai = arr[i]
                while stack and arr[stack[-1]] < ai:
                    stack.pop()
                R[i] = stack[-1] if stack else n
                stack.append(i)
            total = 0
            for i in range(n):
                a = i - L[i]
                b = R[i] - i
                c = cnt(a, b)
                if c:
                    total += arr[i] * c
            return total

        neg = [-x for x in nums]
        return maxsum(nums) - maxsum(neg)

