class Solution:
    def minLength(self, s: str, numOps: int) -> int:
        n = len(s)
        # check k = 1
        c0 = 0  # cost to make s match pattern starting with '0'
        for i, ch in enumerate(s):
            want = '0' if i % 2 == 0 else '1'
            if ch != want:
                c0 += 1
        c1 = n - c0
        if min(c0, c1) <= numOps:
            return 1

        def cost(k):
            total = 0
            i = 0
            while i < n:
                j = i
                while j < n and s[j] == s[i]:
                    j += 1
                L = j - i
                total += L // (k + 1)
                i = j
            return total

        lo, hi = 2, n
        while lo < hi:
            mid = (lo + hi) // 2
            if cost(mid) <= numOps:
                hi = mid
            else:
                lo = mid + 1
        return lo

