class Solution:
    def countComponents(self, nums: List[int], threshold: int) -> int:
        present = bytearray(threshold + 1)
        big = 0
        for x in nums:
            if x <= threshold:
                present[x] = 1
            else:
                big += 1

        parent = list(range(threshold + 1))

        def find(x):
            p = parent
            while p[x] != x:
                p[x] = p[p[x]]
                x = p[x]
            return x

        for d in range(1, threshold + 1):
            sl = present[d::d]
            idx = sl.find(1)
            if idx < 0:
                continue
            mn = d * (idx + 1)
            # m must satisfy mn * m / d <= threshold  =>  (m//d) <= threshold//mn
            khigh = threshold // mn  # k+1 <= khigh  => k <= khigh-1, so end bound = khigh
            if khigh <= idx + 1:
                continue
            rmn = find(mn)
            k = sl.find(1, idx + 1, khigh)
            while k != -1:
                m = d * (k + 1)
                rm = find(m)
                if rm != rmn:
                    parent[rm] = rmn
                    rmn = find(mn)
                k = sl.find(1, k + 1, khigh)

        roots = set()
        for x in nums:
            if x <= threshold:
                roots.add(find(x))
        return len(roots) + big
